import sys

def is_hill_number(n):
    s = str(n)
    i = 0
    while i < len(s) - 1 and s[i] <= s[i + 1]:
        i += 1
    while i < len(s) - 1 and s[i] >= s[i + 1]:
        i += 1
    return i == len(s) - 1

def count_hill_numbers(n):
    def count_up_to(d, tight, is_increasing, prev_digit, dp):
        if d == 0:
            return 1
        key = (d, tight, is_increasing, prev_digit)
        if key in dp:
            return dp[key]
        limit = int(digits[-d]) if tight else 9
        res = 0
        for digit in range(limit + 1):
            if is_increasing and digit < prev_digit:
                continue
            new_tight = tight and digit == limit
            if digit == prev_digit and not is_increasing:
                res += count_up_to(d - 1, new_tight, False, digit, dp)
            else:
                res += count_up_to(d - 1, new_tight,is_increasing or digit > prev_digit, digit, dp)
        dp[key] = res
        return res

    digits = str(n)
    length = len(digits)
    dp = {}
    total = 0
    for i in range(1, length):
        for start in range(1, 10):
            total += count_up_to(i, False, True, start, {})
    for start in range(1, int(digits[0]) + 1):
        total += count_up_to(length, start == int(digits[0]), True, start, {})
    return total

n = int(sys.stdin.read().strip())
if not is_hill_number(n):
    print(-1)
else:
    print(count_hill_numbers(n))
